\label{defcon1}
The elements of $\Gamma'$ are $\{N_{\gamma}\}$-independent in $\Gamma \cap [0, T]$ if
\begin{equation}\label{ind1}
\sum_{\gamma\in\Gamma'} c_{\gamma} \gamma = 0, \quad \textrm{with } |c_{\gamma}| \leq N_{\gamma},
\end{equation}
implies that all $c_{\gamma} = 0$ and for any $\gamma^{*}\in \Gamma \cap [0, T]$,
\begin{equation}\label{ind2}
\sum_{\gamma\in\Gamma'} c_{\gamma} \gamma = \gamma^{*}, \quad \textrm{with } |c_{\gamma}| \leq N_{\gamma},
\end{equation}
implies that $\gamma^{*} \in \Gamma'$, that $c_{\gamma*} = 1$, and that all other $c_{\gamma} = 0$.

\label{AndThm}
If the elements of $\Gamma'$ are $\{N_{\gamma}\}$-independent in $\Gamma \cap[0,T]$, then
\begin{equation}\label{AndS1}
\liminf_{x\rightarrow\infty} \frac{g(x)}{x^{\sigma_{0}}} \leq r_{0} - \sum_{\gamma \in \Gamma'} \frac{2N_{\gamma}}{N_{\gamma} + 1} |r_{\gamma}| \left(1- \frac{\gamma}{T}\right)
\end{equation}
and
\begin{equation}\label{AndS2}
\limsup_{x\rightarrow\infty} \frac{g(x)}{x^{\sigma_{0}}} \geq r_{0} + \sum_{\gamma \in \Gamma'} \frac{2N_{\gamma}}{N_{\gamma} + 1} |r_{\gamma}| \left(1- \frac{\gamma}{T}\right).
\end{equation}

\label{cond1}
If $S = \left\{\gamma_1,\gamma_2, \cdots, \gamma_n\right\} \subset \mathbb{R}$ is weakly $N_\gamma$-dependent, then there exists a nonzero vector $v\in L(K;S)$ such that $|v|^2 < (n^2+n)N_{\gamma}^2+(2n+2)N_{\gamma}+2$.

\begin{proof}
Consider the following vector $v \in L(K;S),$

$$v=\left(\begin{array}{c}\alpha_1\\ \alpha_2 \\ \vdots \\ \alpha_n \\ K(\alpha_1\gamma_1'+\cdots+\alpha_n\gamma_n')\end{array}\right).$$
The assumptions of the lemma show
\begin{equation*}
\begin{split}
|v|^2&=\alpha_i^2+\cdots+\alpha_n^2+K^2(\alpha_1\gamma_1'+\cdots+\alpha_n\gamma_n')^2 \\
&= \alpha_i^2+\cdots+\alpha_n^2+K^2\{(\alpha_1\gamma_1'+\cdots+\alpha_n\gamma_n')-(\alpha_1\gamma_1+\cdots+\alpha_n\gamma_n)\}^{2}, 
\end{split}
\end{equation*}
since $\alpha_1\gamma_1+\cdots+\alpha_n\gamma_n= 0$. Upon using the upper bounds on $|\alpha_{i}|$ and the fact that $|\gamma_{i} - \gamma_{i}'| < K^{-1}$, it follows that
\begin{equation*}
|v|^{2} < nN_{\gamma}^2+2N_{\gamma}+1+K^2\left(\frac{nN_{\gamma}+1}{K}\right)^2,
\end{equation*}
whence the lemma follows.
\end{proof}

